import express from 'express';
import path from 'path';
import fs from 'fs';
import { createServer as createViteServer } from 'vite';

const app = express();
const PORT = 3000;
const ORDERS_FILE = path.join(process.cwd(), 'orders.json');

app.use(express.json());

// Helper to ensure orders.json exists
function getOrders() {
  try {
    if (!fs.existsSync(ORDERS_FILE)) {
      fs.writeFileSync(ORDERS_FILE, JSON.stringify([], null, 2), 'utf-8');
      return [];
    }
    const data = fs.readFileSync(ORDERS_FILE, 'utf-8');
    return JSON.parse(data);
  } catch (err) {
    console.error('Error reading orders.json:', err);
    return [];
  }
}

function saveOrders(orders: any[]) {
  try {
    fs.writeFileSync(ORDERS_FILE, JSON.stringify(orders, null, 2), 'utf-8');
  } catch (err) {
    console.error('Error writing to orders.json:', err);
  }
}

// API Route: Get all orders
app.get('/api/orders', (req, res) => {
  const orders = getOrders();
  res.json({ success: true, count: orders.length, orders });
});

// API Route: Create new order and save to orders.json
app.post('/api/orders', (req, res) => {
  const newOrder = req.body;
  if (!newOrder || (!newOrder.fullname && !newOrder.orderId)) {
    return res.status(400).json({ success: false, message: 'بيانات الطلب غير مكتملة' });
  }

  const orders = getOrders();
  const existingIndex = orders.findIndex((o: any) => o.orderId === newOrder.orderId);

  if (existingIndex !== -1) {
    orders[existingIndex] = {
      status: orders[existingIndex].status || 'قيد التأكيد',
      ...newOrder
    };
  } else {
    const orderWithTimestamp = {
      status: newOrder.status || 'قيد التأكيد',
      ...newOrder,
      createdAt: newOrder.createdAt || new Date().toISOString()
    };
    orders.unshift(orderWithTimestamp);
  }

  saveOrders(orders);

  res.status(201).json({
    success: true,
    message: 'تم تسجيل الطلب بنجاح في قاعدة البيانات orders.json',
    totalOrders: orders.length
  });
});

// API Route: Update an order (e.g. status)
app.patch('/api/orders/:id', (req, res) => {
  const { id } = req.params;
  const updates = req.body;
  let orders = getOrders();
  const index = orders.findIndex((o: any) => o.orderId === id);

  if (index === -1) {
    return res.status(404).json({ success: false, message: 'الطلب غير موجود' });
  }

  orders[index] = { ...orders[index], ...updates };
  saveOrders(orders);

  res.json({ success: true, message: 'تم تحديث الطلب بنجاح', order: orders[index] });
});

// API Route: Delete a specific order
app.delete('/api/orders/:id', (req, res) => {
  const { id } = req.params;
  let orders = getOrders();
  const initialLength = orders.length;
  orders = orders.filter((o: any) => o.orderId !== id);

  if (orders.length === initialLength) {
    return res.status(404).json({ success: false, message: 'الطلب غير موجود' });
  }

  saveOrders(orders);
  res.json({ success: true, message: 'تم حذف الطلب من قاعدة البيانات', remaining: orders.length });
});

// API Route: Clear all orders
app.delete('/api/orders', (req, res) => {
  saveOrders([]);
  res.json({ success: true, message: 'تم إفراغ قاعدة البيانات orders.json بنجاح' });
});

async function startServer() {
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
